<script setup lang="ts">
import {ref,computed,watch,onBeforeUnmount} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import * as api from '@/api/practice'
import * as subjective from '@/api/practice-subjective'
import {parseFilters,filterQuery,sectionFilters} from '@/practice/catalog-query'
import {catalogDateCounts} from '@/practice/catalog-date-counts'
import PracticePaperLibrary from './PracticePaperLibrary.vue'
import PracticeFilters from '@/components/practice/PracticeFilters.vue'
import PracticeMistakes from '@/components/practice/PracticeMistakes.vue'
import {useAuthStore} from '@/stores/auth'
import {useAuthDialogStore} from '@/stores/auth-dialog'
import {getGeneration,onRemoteIdentityChange} from '@/auth/token-session'
import {errorMessage} from '@/api/identity'
import '@/styles/practice.css'
import '@/styles/practice-catalog.css'
import {rememberLibrary} from '@/practice/library-memory'
const props=defineProps<{original?:boolean}>()
const route=useRoute(),router=useRouter(),auth=useAuthStore(),login=useAuthDialogStore(),filters=ref(parseFilters(route.query)),tab=ref('sets'),rows=ref<api.SetSummary[]>([]),history=ref<api.Attempt[]>([]),mistakes=ref<api.Mistake[]>([]),mistakeStatus=ref('PENDING'),facets=ref<api.Facets>(),total=ref(0),loaded=ref(false),busy=ref(false),actionBusy=ref(false),error=ref(''),filterDialog=ref<HTMLDialogElement>();let epoch=0,controller:AbortController|undefined
const subjectiveRows=ref<subjective.SubjectiveHistory[]>([])
const isSubjectiveSection=computed(()=>['writing','translation'].includes(section.value))
const attemptRoute=(type:string,id:string)=>'/practice/'+(subjective.isSubjective(type)?'subjective-attempts/':'attempts/')+id
const family=computed(()=>route.path==='/practice/postgraduate'?'postgraduate':'cet'),examCodes=computed(()=>family.value==='cet'?['CET4','CET6']:['POSTGRAD1','POSTGRAD2']),section=ref('reading')
const collection=computed(()=>props.original?'ORIGINAL':route.query.collection==='PAST'||route.query.collection==='ORIGINAL'?route.query.collection:undefined)
const sectionLabels:Record<string,string>={writing:'写作',listening:'听力',reading:'阅读',translation:'翻译',paper:'整卷'}
const plannedLabel=computed(()=>section.value!=='reading'&&!(['listening','writing','translation'].includes(section.value)&&filters.value.exam==='CET4')?sectionLabels[section.value]:filters.value.exam==='CET6'?'六级':filters.value.exam==='POSTGRAD2'?'考研英语二':filters.value.exam==='POSTGRAD1'?'考研英语一':'')
function selectSection(value:string){filters.value.readingType='';filters.value.listeningType='';filters.value.page=1;void router.replace({query:{...Object.fromEntries(filterQuery(filters.value)),tab:tab.value,...(collection.value?{collection:collection.value}:{}),section:value==='reading'?undefined:value,...(tab.value==='mistakes'?{mistakeStatus:mistakeStatus.value}:{})}})}
const readingLabels:Record<string,string>={DETAILED:'仔细阅读',CLOZE:'选词填空',MATCH:'长篇匹配',LISTENING:'整套听力',WRITING:'写作',TRANSLATION:'翻译'}
function catalogTitle(row:api.SetSummary){
  const m=row.metadata
  const exam:Record<string,string>={CET4:'四级',CET6:'六级',POSTGRAD_1:'考研英语一',POSTGRAD_2:'考研英语二'}
  if(m.sourceKind!=='PAST'||!m.year||!m.month||!m.paperNo||!exam[row.examCode])return m.titleZh||m.title
  let type=row.readingType==='LISTENING'?'听力':readingLabels[row.readingType]
  if(row.readingType==='DETAILED'){
    if(m.titleZh.includes('第一篇'))type+='（一）'
    else if(m.titleZh.includes('第二篇'))type+='（二）'
  }
  return type?`${m.year}年${m.month}月${exam[row.examCode]} 第${m.paperNo}套 ${type}`:m.titleZh||m.title
}

const startIds=new Map<string,string>();let retryCommand:{id:string;requestId:string}|undefined
function permitted(target:string){if(auth.user)return true;login.request(target);return false}
async function load(){const n=++epoch,g=getGeneration();controller?.abort();controller=new AbortController();busy.value=true;error.value='';try{if(!['reading','listening','writing','translation'].includes(section.value)){rows.value=[];history.value=[];mistakes.value=[];facets.value=undefined;total.value=0;return}const q=filterQuery(filters.value);q.set('section',section.value);if(tab.value==='sets'){if(!auth.user&&filters.value.state){login.request(route.fullPath);return}const [page,f]=await Promise.all([api.practiceSets(q,controller.signal),catalogDateCounts(q,query=>api.practiceFacets(query,controller!.signal),'year')]);if(n===epoch&&g===getGeneration()){rows.value=page.items;facets.value=f;total.value=page.total;loaded.value=true}}else if(permitted(route.fullPath)){const dateQuery=new URLSearchParams(q);dateQuery.delete('state');dateQuery.delete('status');if(tab.value==='history'){if(q.get('state')==='NOT_STARTED')q.delete('state');q.delete('status');if(isSubjectiveSection.value){const [page,f]=await Promise.all([subjective.subjectiveHistory(q,controller.signal),api.practiceFacets(dateQuery,controller.signal)]);if(n===epoch&&g===getGeneration()){subjectiveRows.value=page.items;facets.value=f;total.value=page.total;loaded.value=true}}else{const [page,f]=await Promise.all([api.practiceHistory(q,controller.signal),api.practiceFacets(dateQuery,controller.signal)]);if(n===epoch&&g===getGeneration()){history.value=page.items;facets.value=f;total.value=page.total;loaded.value=true}}}else{q.set('status',mistakeStatus.value);const [page,f]=await Promise.all([api.practiceMistakes(q,controller.signal),api.practiceFacets(dateQuery,controller.signal)]);if(n===epoch&&g===getGeneration()){mistakes.value=page.items;facets.value=f;total.value=page.total;loaded.value=true}}}}catch(e){if(n===epoch&&!(e instanceof DOMException&&e.name==='AbortError'))error.value=errorMessage(e)}finally{if(n===epoch)busy.value=false}}
async function apply(){const query={...Object.fromEntries(filterQuery(filters.value)),tab:tab.value,...(collection.value?{collection:collection.value}:{}),...(section.value!=='reading'?{section:section.value}:{}),...(tab.value==='mistakes'?{mistakeStatus:mistakeStatus.value}:{})};if(route.fullPath===router.resolve({path:route.path,query}).fullPath)await load();else await router.replace({query})}
function selectTab(value:string){if(value!=='sets'&&!permitted(router.resolve({path:route.path,query:{...route.query,tab:value}}).fullPath))return;tab.value=value;filters.value.page=1;void apply()}
function page(n:number){filters.value.page=n;void apply()}
async function start(row:api.SetSummary){if(actionBusy.value||!row.setVersionId)return;if(!permitted(router.resolve({path:route.path,query:{...route.query,start:row.id}}).fullPath))return;if(row.currentAttemptId){await router.push({path:attemptRoute(row.readingType,row.currentAttemptId),query:{returnTo:route.fullPath}});return}const g=getGeneration(),n=epoch;actionBusy.value=true;error.value='';const requestId=startIds.get(row.id)||crypto.randomUUID();startIds.set(row.id,requestId);try{const t=await (subjective.isSubjective(row.readingType)?subjective.startSubjective(row.id,row.setVersionId,requestId):api.startPractice(row.id,row.setVersionId,requestId));if(g===getGeneration()&&n===epoch){startIds.delete(row.id);await router.push({path:attemptRoute(row.readingType,t.id),query:{returnTo:route.fullPath}})}}catch(e){if(g===getGeneration())error.value=errorMessage(e)}finally{actionBusy.value=false}}
async function retry(id:string){if(actionBusy.value)return;const g=getGeneration();actionBusy.value=true;error.value='';if(retryCommand?.id!==id)retryCommand={id,requestId:crypto.randomUUID()};try{const t=await api.retryPracticeMistakes(id,retryCommand.requestId);if(g===getGeneration()){retryCommand=undefined;await router.push({path:'/practice/attempts/'+t.id,query:{returnTo:route.fullPath}})}}catch(e){if(g===getGeneration())error.value=errorMessage(e)}finally{actionBusy.value=false}}
const off=onRemoteIdentityChange(()=>{epoch++;controller?.abort();history.value=[];subjectiveRows.value=[];mistakes.value=[];rows.value=[];total.value=0;loaded.value=false;startIds.clear();retryCommand=undefined;actionBusy.value=false;void load()})
watch(()=>route.fullPath,async()=>{filters.value=parseFilters(route.query);if(props.original){filters.value.exam='';filters.value.readingType=''}if(collection.value){filters.value.source=collection.value;if(collection.value==='ORIGINAL'){filters.value.year='';filters.value.month='';filters.value.paperNo=''}}if(!props.original&&!examCodes.value.includes(filters.value.exam))filters.value.exam=examCodes.value[0]!;section.value=['writing','listening','translation','paper'].includes(String(route.query.section))?String(route.query.section):'reading';filters.value=sectionFilters(filters.value,section.value);filters.value.listeningType='';const canonical={...route.query};let clean=false;if(collection.value==='PAST'&&(!route.query.tab||route.query.tab==='sets')){for(const key of ['q','state','topic','paperNo'] as const){filters.value[key]='';if(key in canonical){delete canonical[key];clean=true}}if(filters.value.sort!=='LATEST'){filters.value.sort='LATEST';canonical.sort='LATEST';clean=true}}for(const key of ['readingType','listeningType'] as const){if(String(route.query[key]||'')!==filters.value[key]){if(filters.value[key])canonical[key]=filters.value[key];else delete canonical[key];clean=true}}if('listeningMode' in canonical){delete canonical.listeningMode;clean=true}if(clean){await router.replace({query:canonical});return}tab.value=['history','mistakes'].includes(String(route.query.tab))?String(route.query.tab):'sets';if(isSubjectiveSection.value&&tab.value==='mistakes')tab.value='sets';mistakeStatus.value=route.query.mistakeStatus==='RESOLVED'?'RESOLVED':'PENDING';const remembered=filterQuery(filters.value);if(section.value!=='reading')remembered.set('section',section.value);if(!props.original)rememberLibrary(family.value==='cet'?'/practice/cet':'/practice/postgraduate',remembered.toString());await load();if(auth.user&&route.query.start){const row=rows.value.find(r=>r.id===route.query.start);if(row){await router.replace({query:{...route.query,start:undefined}});void start(row)}}},{immediate:true});onBeforeUnmount(()=>{epoch++;controller?.abort();off()})
</script>
<template><PracticePaperLibrary v-if="!original&&family==='cet'&&section==='paper'"/><section v-else class="practice-page practice-library practice-study-library practice-catalog-page" :class="{'practice-original-library':original}"><RouterLink v-if="!original" :to="{path:'/practice',query:{source:filters.source==='ORIGINAL'?'ORIGINAL':'PAST'}}">← 返回考试类别</RouterLink><header class="practice-heading"><div><h2 v-if="original">原创题目</h2><h1 v-else>{{family==='cet'?'大学英语（四六级）':'考研英语'}}</h1></div></header><nav class="practice-section-nav" aria-label="练习题型"><button v-for="(label,key) in (original?{reading:'阅读',writing:'写作',translation:'翻译'}:sectionLabels)" :key="key" :aria-pressed="section===key" @click="selectSection(key)">{{label}}</button></nav><p v-if="!original&&plannedLabel" class="practice-planned-label">{{plannedLabel}} · 规划中</p><div class="practice-tabs" role="tablist" aria-label="专项题库栏目"><button v-for="item in [{id:'sets',label:'全部题组'},{id:'history',label:'我的练习'},...(!isSubjectiveSection?[{id:'mistakes',label:'错题本'}]:[])]" :key="item.id" role="tab" :aria-selected="tab===item.id" @click="selectTab(item.id)">{{item.label}}</button></div><button class="practice-filter-toggle" @click="filterDialog?.showModal()">筛选题组</button><div class="practice-library-body"><aside class="practice-desktop-filters"><PracticeFilters v-model="filters" :section="section" catalog-layout :facets="facets" :dates-pending="busy||!!error" :history="tab==='history'" :exam-codes="original?undefined:examCodes" :original="original" :source-locked="!!collection" @apply="apply"/><p v-if="facets&&tab==='sets'" class="practice-hint">当前匹配：{{facets.source.filter(f=>!collection||f.value===collection).map(f=>(f.value==='ORIGINAL'?'原创':'真题')+' '+f.count+'组').join(' · ')||'暂无内容'}}</p></aside><div class="practice-library-results" :aria-busy="busy"><p v-if="busy" class="practice-list-loading" role="status">正在加载…</p><p v-if="error" class="practice-notice practice-error" role="alert">{{error}}<button @click="load">重新加载列表</button></p><p class="practice-hint">匹配 {{loaded?total:'—'}} {{tab==='sets'?'组':tab==='history'?'轮练习':'道题'}}</p><div v-if="tab==='sets'" class="practice-rows"><article v-for="r in rows" :key="r.id" class="practice-card practice-set-row practice-catalog-row"><div class="practice-set-copy"><h2>{{r.metadata.sourceKind==='ORIGINAL'?r.metadata.title:catalogTitle(r)}}</h2></div><div class="practice-set-meta"><span class="practice-tag">{{readingLabels[r.readingType]||'阅读'}} · {{r.questionCount}}题</span><span v-if="r.personalState==='IN_PROGRESS'||r.personalState==='COMPLETED'" class="practice-tag">{{r.personalState==='IN_PROGRESS'?'可继续':'已完成'}}</span><span v-if="r.metadata.month" class="practice-tag">{{r.metadata.month}}月</span><span v-if="r.metadata.sourceKind==='ORIGINAL'" class="practice-hint">原创练习</span></div><button class="button-primary" :disabled="actionBusy" @click="start(r)">{{r.currentAttemptId?'继续练习':'开始练习'}}</button></article></div><div v-else-if="tab==='history'" class="practice-rows"><template v-if="isSubjectiveSection"><article v-for="t in subjectiveRows" :key="t.id" class="practice-card"><span class="practice-tag">{{readingLabels[t.readingType]}} · {{t.status==='COMPLETED'?'已提交':'草稿'}}</span><h2>{{t.title}}</h2><p>{{t.wordCount}} 词 · {{new Date(t.completedAt||t.startedAt).toLocaleString()}}</p><RouterLink :to="{path:attemptRoute(t.readingType,t.id),query:{returnTo:route.fullPath}}">{{t.status==='COMPLETED'?'查看作答与参考':'继续练习'}}</RouterLink></article></template><template v-else><article v-for="t in history" :key="t.id" class="practice-card"><span class="practice-tag">{{t.kind==='FULL'?'整组练习':'错题重做'}} · {{t.status==='COMPLETED'?'已完成':'进行中'}}</span><h2>{{t.title}}</h2><p v-if="t.status==='COMPLETED'">正确 {{t.correctCount}} / {{t.total}}</p><RouterLink :to="{path:'/practice/attempts/'+t.id,query:{returnTo:route.fullPath}}">{{t.status==='COMPLETED'?'查看成绩解析':'继续练习'}}</RouterLink></article></template></div><template v-else><label>错题状态<select v-model="mistakeStatus" @change="filters.page=1;apply()"><option value="PENDING">待订正</option><option value="RESOLVED">已订正</option></select></label><PracticeMistakes :items="mistakes" :busy="actionBusy" @retry="retry" @view="router.push({path:'/practice/attempts/'+$event,query:{returnTo:route.fullPath}})"/></template><div v-if="!busy&&!total&&!error" class="practice-empty">{{tab==='sets'?(section==='listening'?'听力暂无匹配试卷，可以切换年份或月份。':'暂无匹配题组。可以清空筛选；未开放分类暂无内容。'):tab==='history'?'还没有符合条件的练习。完成或保存的任务会出现在这里。':'当前没有符合条件的错题。'}}</div><details v-if="tab==='sets'&&rows.length" class="practice-catalog-notes"><summary>题目与来源说明</summary><article v-for="r in rows" :key="r.id"><h3>{{r.metadata.titleZh||r.metadata.title}}</h3><p v-if="r.metadata.titleZh&&r.metadata.titleZh!==r.metadata.title">{{r.metadata.title}}</p><p>{{r.metadata.sourceKind==='PAST'?(r.metadata.year+'年'+r.metadata.month+'月 · 第'+r.metadata.paperNo+'套 · '):'原创 · '}}{{r.metadata.sourceName}}</p><p>{{r.metadata.usageNote}}</p></article></details><nav class="practice-pagination" aria-label="练习分页"><button :disabled="busy||filters.page<=1" @click="page(filters.page-1)">上一页</button><span>第 {{filters.page}} / {{Math.max(1,Math.ceil(total/filters.pageSize))}} 页</span><button :disabled="busy||filters.page*filters.pageSize>=total" @click="page(filters.page+1)">下一页</button></nav></div></div><dialog ref="filterDialog" class="practice-preview-dialog practice-page"><header class="practice-actions"><h2>筛选题组</h2><button @click="filterDialog?.close()">关闭筛选</button></header><PracticeFilters v-model="filters" :section="section" catalog-layout :facets="facets" :dates-pending="busy||!!error" :history="tab==='history'" :exam-codes="original?undefined:examCodes" :original="original" :source-locked="!!collection" @apply="apply"/><button class="button-primary" @click="apply();filterDialog?.close()">查看匹配结果</button></dialog></section></template>


